<script lang="ts">
 import { api, ApiError } from '@nrynss/chaaya/keel';
 import { resolve } from '$app/paths';
 import { errorNotice, unknownAreaNotice } from '../errors/notice';
 import { areas, verdicts, levels, parseCard, cardID, evidence, leadEvidence, type Card } from './contract';
 import Quote from './Quote.svelte';
 let { id } = $props<{ id: string }>();
 let card = $state<Card>(); let loadState = $state<'loading' | 'ready' | 'missing' | 'failed'>('loading'); let retry = $state(0);
 let shareURL = $state(''); let shareMessage = $state(''); let selected = $state<string[]>([]); let alive = true;
 $effect(() => {
  const currentID = id; const attempt = retry; void attempt; const controller = new AbortController(); alive = true;
  card = undefined; selected = []; shareMessage = ''; loadState = 'loading'; shareURL = '';
  if (!cardID(currentID)) { loadState = 'missing'; return () => { alive = false; }; }
  shareURL = new URL(resolve('/card/[id]', { id: currentID }), window.location.origin).href;
  (async () => { try { const response = await api<unknown>(`/api/cards/${encodeURIComponent(currentID)}`, { signal: controller.signal, timeoutMs: 15000 }); const parsed = parseCard(response, currentID); if (!controller.signal.aborted) { card = parsed; loadState = 'ready'; } } catch (error) { if (!controller.signal.aborted) loadState = error instanceof ApiError && error.code === 'not_found' ? 'missing' : 'failed'; } })();
  return () => { alive = false; controller.abort(); };
 });
 let lead = $derived(card ? leadEvidence(card) : undefined);
 async function share() { const url = shareURL; try { if (!navigator.clipboard?.writeText) throw new Error('Clipboard unavailable'); await navigator.clipboard.writeText(url); if (alive && shareURL === url) shareMessage = 'Link copied.'; } catch { if (alive && shareURL === url) shareMessage = 'Copy the address below to share this card.'; } }
 const missingNotice = errorNotice({ code: 'not_found' });
 const unanswered = unknownAreaNotice();
 const checkedDate = (value: string) => new Intl.DateTimeFormat('en', { dateStyle: 'long', timeStyle: 'short', timeZone: 'UTC' }).format(new Date(value)) + ' UTC';
 const cost = (value: Card) => '$' + ((value.stats.read_cost_nano + value.stats.judge_cost_nano) / 1e9).toLocaleString('en-US', { minimumFractionDigits: 4, maximumFractionDigits: 9 });
</script>
<svelte:head><title>Before Yes - {card ? `${card.title} - ${verdicts[card.verdict]}` : 'Your card'}</title></svelte:head>
<div class="reading card"><a class="back" href={resolve('/')}>← Ask about a title</a>
 {#if loadState === 'loading'}<h1>Reading your card…</h1><p role="status">Opening the decision and its evidence.</p>
 {:else if loadState === 'missing'}<h1>{missingNotice.situation}</h1><p role="alert">{missingNotice.next}</p><button onclick={() => retry++}>Try again</button>
 {:else if loadState !== 'ready' || !card}<h1>The card couldn’t be opened.</h1><p role="alert">Try again to load the evidence. You can also return to the ask page.</p><button onclick={() => retry++}>Try again</button>
 {:else}
  <header class="answer"><h1 class:stop={card.verdict === 'no'} class:yes={card.verdict === 'yes'} class:caution={card.verdict === 'unclear' || card.verdict === 'yes_with_settings'}>{verdicts[card.verdict]}</h1><h2 class="title">{card.title}</h2><p class="metadata">For age {card.age} <span aria-hidden="true">·</span> Checked <time datetime={card.checked_at}>{checkedDate(card.checked_at)}</time></p></header>
  {#if card.verdict === 'no' && lead}<section class="lead" aria-labelledby="lead-label"><h2 id="lead-label">Why this is a concern</h2><Quote finding={lead.finding} prominent /></section>{/if}

  {#if card.settings.length}<section class="settings" aria-labelledby="settings-title"><h2 id="settings-title">Settings to change</h2><p>Change these settings on your child’s device, then tick them here. Ticking a box doesn’t change the device’s settings.</p>{#each card.settings as setting (setting)}<div class="setting"><label><input type="checkbox" value={setting} bind:group={selected} /><span>{setting}</span></label>{#each card.grades.filter(g => g.setting === setting) as grade (grade.area)}{#each evidence(card, grade) as finding (finding.id)}<Quote {finding} />{/each}{/each}</div>{/each}</section>{/if}
  <section class="areas" aria-labelledby="areas-title"><h2 id="areas-title">What the evidence says</h2>{#each areas as [areaID, label] (areaID)}{@const grade = card.grades.find(g => g.area === areaID)!}<article class="area" data-area={areaID}><div class="area-heading"><h3>{label}</h3><span class="grade" class:stop={grade.level === 'flag'} class:yes={grade.level === 'ok'} class:caution={grade.level === 'ok_with_setting' || grade.level === 'unknown'}>{levels[grade.level]}</span></div>{#if grade.reason?.trim()}<p>{grade.reason}</p>{:else if grade.level === 'unknown'}<p>{unanswered.situation}</p><p>{unanswered.next}</p>{:else}<p>The supplied evidence supports this grade; no further explanation was provided.</p>{/if}{#if grade.setting}<p class="named-setting">Setting: {grade.setting}</p>{/if}{#if grade.level === 'flag'}{#each evidence(card, grade) as finding (finding.id)}<Quote {finding} />{/each}{:else if grade.findings.length}<details><summary>Read the source quotes</summary>{#each evidence(card, grade) as finding (finding.id)}<Quote {finding} />{/each}</details>{/if}</article>{/each}</section>
  {#if card.alternatives.some(a => a.status === 'checked') || card.alternatives_note}<section class="alternatives" aria-labelledby="alternatives-title"><h2 id="alternatives-title">Other titles to consider</h2>{#each card.alternatives.filter(a => a.status === 'checked') as alternative (alternative.card_id)}<article><h3>{alternative.title}</h3><p class="alternative-verdict">{verdicts[alternative.verdict]}</p><p>{alternative.reason}</p><div class="actions"><a href={resolve('/card/[id]', { id: alternative.card_id })}>View check</a><a href={resolve('/compare/[a]/[b]', { a: card.id, b: alternative.card_id })}>Compare titles</a></div></article>{/each}{#if card.alternatives_note}<p class="alternative-note">{card.alternatives_note === "More alternatives when today's checks reset" ? 'More alternatives can be checked when the daily limit resets.' : card.alternatives_note}</p>{/if}</section>{/if}
  <section class="small-print" aria-labelledby="details-title"><h2 id="details-title">About this check</h2><dl>
   <div><dt>Title type</dt><dd>{card.kind_label}</dd></div><div><dt>Sources read</dt><dd>{card.stats.sources}</dd></div><div><dt>Reviews read</dt><dd>{card.stats.reviews}{card.stats.review_source === 'feed' ? ' · App Store review feed' : card.stats.review_source === 'page' ? ' · App Store web page' : ' · No review source'}</dd></div>
   <div><dt>Quotes that couldn’t be verified</dt><dd>{card.stats.drops.unquoted}</dd></div><div><dt>Findings without a source quote</dt><dd>{card.stats.drops.no_quote}</dd></div><div><dt>Other excluded findings</dt><dd>{card.stats.drops.bad_area} unrecognised checklist area · {card.stats.drops.bad_stance} unrecognised finding category · {card.stats.drops.duplicates} duplicates</dd></div>
   <div><dt>Source sections</dt><dd>{card.stats.chunks} sections · {card.stats.failed_chunks} couldn’t be read</dd></div><div><dt>Source types not found</dt><dd>{card.stats.missing_kinds.join(', ') || 'None reported'}</dd></div><div><dt>Areas checked a second time</dt><dd>{card.stats.conflicted_areas.map(a => areas.find(([id]) => id === a)?.[1]).join(', ') || 'None reported'}</dd></div>
   <div><dt>Checklist version</dt><dd>{card.checklist_version}</dd></div><div><dt>AI model used to read sources</dt><dd>{card.stats.reader_model}</dd></div><div><dt>AI model used to assess findings</dt><dd>{card.stats.judge_model}</dd></div><div><dt>AI processing cost</dt><dd>{cost(card)} USD</dd></div><div><dt>Search credits used</dt><dd>{card.stats.tavily_credits}</dd></div>
  </dl><p>This guidance reflects the sources available when the check was run.</p></section>
  <section class="share" aria-label="Share this card"><button onclick={share}>Copy card link</button><p role="status">{shareMessage}</p><label for="share-url">Card link<textarea id="share-url" readonly value={shareURL} rows="2" onclick={(event) => event.currentTarget.select()}></textarea></label></section>
 {/if}
</div>
<style>
 .card { max-width: 760px; } .answer h1 { font-size: clamp(2.75rem, 6vw, 4rem); margin-bottom: 20px; letter-spacing: -.035em; } .title { font-size: clamp(1.5rem, 3vw, 2rem); margin-bottom: 12px; } .metadata { font-size: .85rem; margin-bottom: 28px; }
 .stop { color: var(--stop); } .yes { color: var(--ok); } .caution { color: var(--warn); }
 .lead { background: var(--stop-soft); border-left: 3px solid var(--stop); padding: 20px; margin-bottom: 24px; } .lead h2 { color: var(--dim); font-family: var(--font-ui); font-size: .78rem; letter-spacing: 0; font-weight: 600; margin-bottom: 16px; }
 .share { border-block: 1px solid var(--line-soft); padding: 16px 0; margin-top: 32px; } button { min-height: 48px; border: 1px solid var(--line); border-radius: var(--radius-control); background: var(--surface); color: var(--text); padding: 10px 16px; font: inherit; cursor: pointer; } .share p { font-size: .8rem; margin: 8px 0; } .share label { font-size: .75rem; color: var(--dim); display: block; } .share textarea { display: block; width: 100%; min-height: 48px; font: inherit; color: var(--text); border: 1px solid var(--line); background: var(--surface); padding: 10px; border-radius: var(--radius-control); }
 .settings { background: var(--surface); border: 1px solid var(--line); padding: 22px; margin-bottom: 44px; border-radius: var(--radius-panel); } .settings > p { font-size: .85rem; } .setting { padding-block: 16px; border-top: 1px solid var(--line-soft); } .setting label { display: flex; align-items: center; gap: 12px; min-height: 48px; cursor: pointer; font-size: .95rem; color: var(--text); } input[type=checkbox] { flex: 0 0 20px; width: 20px; height: 20px; accent-color: var(--accent); }
 .area { border-top: 1px solid var(--line); padding: 24px 0; } .area-heading { display: flex; align-items: baseline; flex-wrap: wrap; justify-content: space-between; gap: 8px 20px; margin-bottom: 12px; } .area h3 { font-size: 1.15rem; margin: 0; } .grade { font-size: .8rem; font-weight: 650; } .area > p { font-size: .95rem; margin-bottom: 12px; } .named-setting { color: var(--text); } summary { min-height: 48px; padding: 12px 0; cursor: pointer; color: var(--accent); font-size: .85rem; }
 .alternatives { margin-top: 36px; } .alternatives article { padding: 24px 0; border-block: 1px solid var(--line-soft); } .alternatives h3 { font-family: Georgia, Cambria, serif; font-size: 1.45rem; font-weight: 400; } .alternative-verdict { color: var(--text); font-size: .85rem; font-weight: 600; } .alternatives p { margin-bottom: 12px; } .actions { display: flex; flex-wrap: wrap; gap: 8px 24px; } .actions a { display: inline-flex; align-items: center; min-height: 48px; font-size: .9rem; } .alternative-note { margin-top: 20px; font-size: .9rem; }
 .small-print { border-top: 1px solid var(--line); margin-top: 48px; padding-top: 26px; } .small-print h2 { font-size: 1.35rem; } dl { margin: 0 0 24px; font-size: .78rem; } dl > div { display: grid; grid-template-columns: minmax(100px, .8fr) minmax(0, 1.2fr); gap: 16px; padding: 8px 0; } dt { color: var(--dim); } dd { margin: 0; color: var(--text); overflow-wrap: anywhere; } .small-print > p { font-size: .78rem; }
</style>
